namespace CSharpPracticum.Tasks.Level2;
internal class Task23_Nullable:ITask{public string Title=>"Задание 23: Nullable-типы, ??, ?. ";public string Description=>"Показать безопасную работу со значением, которого может не быть.";public string[] Requirements=>new[]{"FindValue(string key) возвращает int? или null.","Использовать ??, ?., HasValue и Value.","Показать найденный и отсутствующий ключ."};private static int? FindValue(string k)=>k=="есть"?42:null;private class Info{public string Name{get;set;}="пример";}public void Run(){foreach(string key in new[]{"есть","нет"}){int? value=FindValue(key);Console.WriteLine($"{key}: {value??0}");if(value.HasValue)Console.WriteLine(value.Value);Info? info=key=="есть"?new Info():null;Console.WriteLine(info?.Name??"нет объекта");}}}
